#include "recordbase/dataset_engine.hpp"
#include <algorithm>
namespace recordbase {
static std::string id(const char*p,const std::string&s){return std::string(p)+s;}
bool DatasetEngine::add_catalog(Catalog c){if(c.id.empty()||c.name.empty())return false;if(tree_.size()==0&&!tree_.create_root("recordbase","RecordBase"))return false;return tree_.add(id("catalog:",c.id),c.name,NodeKind::Branch,"recordbase");}
bool DatasetEngine::add_dataset(const std::string&cid,Dataset d){if(d.id.empty()||d.name.empty())return false;auto p=id("catalog:",cid);if(!tree_.contains(p)||tree_.contains(id("dataset:",d.id)))return false;auto n=id("dataset:",d.id);if(!tree_.add(n,d.name,NodeKind::SubBranch,p))return false;DataRecord r{d.id,d.name,{{"source",DataValue::string(d.source)},{"target",DataValue::string(d.target)},{"date",DataValue::string(d.date)},{"start_time",DataValue::string(d.start_time)},{"end_time",DataValue::string(d.end_time)},{"total_rows",DataValue::integer(d.total_rows)},{"rows_indexed",DataValue::integer(d.rows_indexed)}}};return tree_.attach_record(n,std::move(r));}
bool DatasetEngine::add_entry(const std::string&did,Entry e){auto p=id("dataset:",did);if(!tree_.contains(p)||e.id.empty()||tree_.contains(id("entry:",e.id)))return false;auto n=id("entry:",e.id);if(!tree_.add(n,e.name,NodeKind::Node,p))return false;return tree_.attach_record(n,{e.id,e.name,{{"address",DataValue::string(e.address)},{"city",DataValue::string(e.city)}}});}
bool DatasetEngine::add_transaction(const std::string&did,Transaction t){auto p=id("dataset:",did);if(!tree_.contains(p)||t.id.empty()||tree_.contains(id("transaction:",t.id))||!tree_.contains(id("entry:",t.entry_id)))return false;auto n=id("transaction:",t.id);if(!tree_.add(n,n,NodeKind::SubNode,p))return false;return tree_.attach_record(n,{t.id,t.id,{{"entry_id",DataValue::string(t.entry_id)},{"dataset_id",DataValue::string(t.dataset_id)},{"amount",DataValue::decimal(t.amount)}}});}
bool DatasetEngine::add_index(const std::string&did,IndexKey k){auto p=id("dataset:",did);if(!tree_.contains(p)||k.id.empty()||tree_.contains(id("index:",k.id)))return false;auto n=id("index:",k.id);if(!tree_.add(n,k.key,NodeKind::Data,p))return false;return tree_.attach_record(n,{k.id,k.key,{{"dataset_id",DataValue::string(k.dataset_id)},{"available",DataValue::boolean(k.available)}}});}
const Dataset* DatasetEngine::dataset(const std::string&x) const {static Dataset d;auto n=tree_.find(id("dataset:",x));if(!n||n->records.empty())return nullptr;d.id=x;d.name=n->name;auto&f=n->records.front().fields;auto get=[&](const char*k){auto i=f.find(k);return i==f.end()?std::string{}:i->second.text;};d.source=get("source");d.target=get("target");d.date=get("date");d.start_time=get("start_time");d.end_time=get("end_time");return &d;}
const Entry* DatasetEngine::entry(const std::string&x) const {static Entry e;auto n=tree_.find(id("entry:",x));if(!n||n->records.empty())return nullptr;e.id=x;e.name=n->name;auto&f=n->records.front().fields;auto a=f.find("address"),c=f.find("city");e.address=a==f.end()?"":a->second.text;e.city=c==f.end()?"":c->second.text;return &e;}
bool DatasetEngine::remove(const std::string&x){return tree_.remove(x);}
bool DatasetEngine::validate() const{return tree_.validate();}
std::vector<const TreeNode*> DatasetEngine::datasets() const{return tree_.find_by_kind(NodeKind::SubBranch);}
} // namespace recordbase
